const inlineMarkdown = (source) => {
  const code = [];
  let html = escapeHtml(source).replace(/`([^`]+)`/g, (_, value) => `\u0000${code.push(value) - 1}\u0000`);
  html = html.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>').replace(/\*([^*]+)\*/g, '<em>$1</em>');
  return html.replace(/\u0000(\d+)\u0000/g, (_, index) => `<se-code>${code[Number(index)]}</se-code>`);
};

const renderMarkdown = (source = '') => {
  const lines = source.trim().replaceAll('\r', '').split('\n');
  const html = [];
  let paragraph = [];
  const flush = () => { if (paragraph.length) html.push(`<p>${inlineMarkdown(paragraph.join(' '))}</p>`); paragraph = []; };

  for (let index = 0; index < lines.length; index += 1) {
    const line = lines[index];
    const fence = line.match(/^```([\w-]*)\s*$/);
    if (fence) {
      flush();
      const code = [];
      while (++index < lines.length && !/^```\s*$/.test(lines[index])) code.push(lines[index]);
      html.push(`<se-code block language="${escapeHtml(fence[1])}">${escapeHtml(code.join('\n'))}</se-code>`);
    } else if (/^#{1,6}\s/.test(line)) {
      flush();
      const level = line.match(/^#+/)[0].length;
      html.push(`<h${level}>${inlineMarkdown(line.slice(level).trim())}</h${level}>`);
    } else if (/^>\s?/.test(line)) {
      flush();
      const quote = [];
      do { quote.push(lines[index].replace(/^>\s?/, '')); index += 1; } while (index < lines.length && /^>\s?/.test(lines[index]));
      index -= 1;
      html.push(`<se-blockquote>${inlineMarkdown(quote.join(' '))}</se-blockquote>`);
    } else if (/^[-*+]\s/.test(line)) {
      flush();
      const items = [];
      do { items.push(`<li>${inlineMarkdown(lines[index].replace(/^[-*+]\s/, ''))}</li>`); index += 1; } while (index < lines.length && /^[-*+]\s/.test(lines[index]));
      index -= 1;
      html.push(`<ul>${items.join('')}</ul>`);
    } else if (!line.trim()) flush();
    else paragraph.push(line.trim());
  }
  flush();
  return html.join('');
};


const defineNativeInput = (tag, type, fallbackLabel) => define(tag, class extends HTMLElement {
  connectedCallback() {
    if (this.dataset.ready) return;
    this.dataset.ready = 'true';
    const id = this.getAttribute('id') || `${tag}-${crypto.randomUUID()}`;
    const label = this.getAttribute('label') || fallbackLabel;
    const attributes = ['name', 'value', 'min', 'max', 'step'].map((name) => this.hasAttribute(name) ? `${name}="${escapeHtml(this.getAttribute(name))}"` : '').filter(Boolean).join(' ');
    this.innerHTML = `<label class="se-label" for="${escapeHtml(id)}">${escapeHtml(label)}${this.hasAttribute('required') ? '<span class="se-required">*</span>' : ''}</label><input class="se-control" id="${escapeHtml(id)}" type="${type}" ${attributes}${this.hasAttribute('required') ? ' required' : ''}${this.hasAttribute('disabled') ? ' disabled' : ''}>`;
  }

  get value() { return this.querySelector('input')?.value || ''; }
  set value(value) { const input = this.querySelector('input'); if (input) input.value = value; }
});

const parseDate = (value) => {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value || '');
  if (!match) return null;
  const date = new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3]));
  return date.getFullYear() === Number(match[1]) && date.getMonth() === Number(match[2]) - 1 && date.getDate() === Number(match[3]) ? date : null;
};

const dateValue = (date) => [date.getFullYear(), date.getMonth() + 1, date.getDate()].map((part, index) => String(part).padStart(index ? 2 : 4, '0')).join('-');

const calendarDays = (year, month) => {
  const first = new Date(year, month, 1);
  const start = new Date(year, month, 1 - first.getDay());
  return Array.from({ length: 42 }, (_, index) => new Date(start.getFullYear(), start.getMonth(), start.getDate() + index));
};

const parseTime = (value) => {
  const match = /^(\d{2}):(\d{2})$/.exec(value || '');
  return match && Number(match[1]) < 24 && Number(match[2]) < 60 ? { hour: Number(match[1]), minute: Number(match[2]) } : null;
};

const timeValue = ({ hour, minute }) => `${String(hour).padStart(2, '0')}:${String(minute).padStart(2, '0')}`;


